import csv
from collections import defaultdict

temp_ts='629b0be5-87d8-548e-97b9-74ee3a313dd4'
set_ts='8ccf446d-e2b0-51fa-9e89-180d61a24d5a'

def load(ts):
    d={}
    with open(VALUES_CSV) as f:
        for tid,timestamp,value in csv.reader(f):
            if tid==ts:
                d[timestamp]=float(value)
    return d

temp=load(temp_ts); setp=load(set_ts)
print(len(temp),len(setp))

def mean_dev(date):
    devs=[]
    for ts,v in temp.items():
        if ts.startswith(date):
            h=ts[11:13]
            if 8<=int(h)<=18:
                if ts in setp:
                    devs.append(v-setp[ts])
    return sum(devs)/len(devs),len(devs)

